"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisTestimonialsContent } from "./components/testimonials/content";
import View0 from "./components/testimonials/variants/01-marquee";
import View1 from "./components/testimonials/variants/02-spotlight";
import View2 from "./components/testimonials/variants/03-grid";
import View3 from "./components/testimonials/variants/04-archive";
import View4 from "./components/testimonials/variants/05-vertical";
const variants={"marquee":View0,"spotlight":View1,"grid":View2,"archive":View3,"vertical":View4};
export type { ArtemisTestimonialsContent, ArtemisTestimonialsImage, ArtemisTestimonialsQuote } from "./components/testimonials/content";
export interface ArtemisTestimonialsProps { className?: string; variant?: "marquee" | "spotlight" | "grid" | "archive" | "vertical"; /** The words on the testimonials; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisTestimonialsContent>; }
export function ArtemisTestimonials({className,variant="marquee",content}:ArtemisTestimonialsProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** A picture, and the words that describe it. */
export interface ArtemisTestimonialsImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** One testimonial: what was said, and who said it. */
export interface ArtemisTestimonialsQuote {
  /** What they said, without quotation marks; marquee, spotlight, grid and vertical add their own. All layouts. */
  quote: string;
  /** Who said it. All layouts. */
  name: string;
  /** Their title and company as one line, such as "Frontend Lead, Workspace". All layouts. */
  role: string;
  /** Their photo. marquee, spotlight, grid and archive, which show the person's initials in its place when you leave it out. */
  avatar?: ArtemisTestimonialsImage;
  /** A short result over the quote, such as "18 days saved". vertical. */
  metric?: string;
}

/** The words on an Artemis testimonials section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisTestimonialsContent {
  /** The short label over the heading; over the quote in spotlight. All layouts. */
  badge: string;
  /** The heading. marquee, grid, archive and vertical. */
  headline?: string;
  /** The heading's second part. marquee and grid reveal it after `headline`, archive starts a new line for it, and vertical runs it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** A sentence beside or under the heading. marquee, grid and archive. */
  subhead?: string;
  /**
   * The testimonials. All layouts. marquee scrolls them in two rows, the first half on top, and eight or more look
   * best; spotlight shows one at a time with a photo button for each, and four look best; grid shows the first one
   * larger; archive pins them in up to three columns; vertical fills three scrolling columns in order, shows the third
   * from 1024px wide, and nine look best.
   */
  quotes: ArtemisTestimonialsQuote[];
  /** The word after the number of quotes, as in "9 dispatches". vertical. */
  countLabel?: string;
  /** A short line beside that count. vertical. */
  note?: string;
}

