import { motion, useAnimationFrame, useMotionValue, useReducedMotion } from "motion/react";
import { useEffect, useRef } from "react";
import { TextReveal } from "./01-marquee/text-reveal";
import type { ArtemisTestimonialsContent, ArtemisTestimonialsQuote } from "../content";
const DEFAULT = {
    badge: "Loved by builders",
    headline: "Teams ship faster",
    headlineAccent: "with Artemis.",
    subhead: "From solo founders to platform teams — premium motion, owned source, and zero theme bugs.",
    quotes: [
        { quote: "Shipped our pricing page in an afternoon. The motion is the part I could never get right by hand.", name: "Morgan Wells", role: "Frontend Lead, Workspace", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "Feels like the components were designed by someone who actually ships products, not just demos.", name: "Avery Stone", role: "Founder, Group A", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "The agent primitives saved us weeks — streaming, tool calls, and thinking states all handled.", name: "Avery Lane", role: "Design Engineer, Group B", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "Copy-paste source means no black-box dependency. We read and own every line we ship.", name: "Jordan Stone", role: "Staff Engineer, Group C", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "Quiet, fast, polished. Our marketing site finally matches the quality of the product.", name: "Morgan Park", role: "Head of Design, Group D", avatar: { src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "" } },
        { quote: "Installed from our own registry in one command. Onboarding new engineers is trivial now.", name: "Liam O'Brien", role: "CTO, Group E", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "Every block reads perfectly in light and dark. We haven't filed a single theme bug.", name: "Robin Ellis", role: "Product Designer, Group F", avatar: { src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "" } },
