        // Today's second row ends with the first quote again.
        { quote: "Shipped our pricing page in an afternoon. The motion is the part I could never get right by hand.", name: "Morgan Wells", role: "Frontend Lead, Workspace", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
    ],
} satisfies ArtemisTestimonialsContent;
/** Up to two initials from a name, shown in place of a missing photo. */
const initials = (name: string) => name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]?.toUpperCase() ?? "").join("");
/** One card. Each row lists its cards twice, so the loop has no seam. */
const card = (item: ArtemisTestimonialsQuote, index: number) => (<figure key={index} className="art:w-[20rem] art:shrink-0 art:rounded-2xl art:border art:border-border/60 art:bg-background art:p-5">
                  <blockquote className="art:text-pretty art:text-foreground art:text-sm art:leading-6">
                    {"“"}
                    {item.quote}
                    {"”"}
                  </blockquote>
                  <figcaption className="art:mt-4 art:flex art:items-center art:gap-3">
                    {item.avatar ? (<img src={item.avatar.src} alt={item.avatar.alt} aria-hidden="true" width="36" height="36" loading="lazy" className="art:size-9 art:shrink-0 art:rounded-full art:border art:border-border/60"/>) : (<span aria-hidden="true" className="art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:border art:border-border/60 art:bg-muted art:font-medium art:text-muted-foreground art:text-xs">
