                      </span>)}
                    <div className="art:min-w-0">
                      <p className="art:truncate art:font-medium art:text-foreground art:text-sm">
                        {item.name}
                      </p>
                      <p className="art:truncate art:text-muted-foreground art:text-xs">
                        {item.role}
                      </p>
                    </div>
                  </figcaption>
                </figure>);
export default function TestimonialsMarquee({ content }: { content?: Partial<ArtemisTestimonialsContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const half = Math.floor(copy.quotes.length / 2);
    const top = copy.quotes.slice(0, half);
    const bottom = copy.quotes.slice(half);
    const section = useRef<HTMLElement>(null);
    const first = useRef<HTMLDivElement>(null);
    const second = useRef<HTMLDivElement>(null);
    const xFirst = useMotionValue(0);
    const xSecond = useMotionValue(0);
    const paused = useRef(false);
    const visible = useRef(false);
    const reduce = useReducedMotion();
    useEffect(() => {
        if (!section.current)
            return;
        const observer = new IntersectionObserver((entries) => {
            for (const entry of entries)
                visible.current = entry.isIntersecting;
        }, { rootMargin: "-10% 0px", threshold: 0 });
        observer.observe(section.current);
        return () => observer.disconnect();
    }, []);
    useAnimationFrame((_, delta) => {
        if (reduce || paused.current || !visible.current)
            return;
        const halfFirst = (first.current?.offsetWidth ?? 0) / 2;
        const halfSecond = (second.current?.offsetWidth ?? 0) / 2;
        if (!halfFirst || !halfSecond)
            return;
        let nextFirst = xFirst.get() - delta * 0.028;
        if (nextFirst <= -halfFirst)
            nextFirst += halfFirst;
        xFirst.set(nextFirst);
        let nextSecond = xSecond.get() + delta * 0.022;
        if (nextSecond >= 0)
            nextSecond -= halfSecond;
        xSecond.set(nextSecond);
    });
    return (<>
      <div className="art:w-full">
        <section ref={section} className="art:w-full">
          <div className="art:mx-auto art:w-full art:max-w-2xl art:text-center">
            <span className="art:inline-flex art:items-center art:rounded-full art:border art:border-border/60 art:bg-background art:px-3 art:py-1 art:font-medium art:text-muted-foreground art:text-xs">
              {copy.badge}
            </span>
            <TextReveal as="h2" text={accent ? [copy.headline, accent] : [copy.headline]} stagger={0.09} yOffset="40%" className="art:mt-5 art:text-balance art:font-sans art:text-foreground art:text-4xl art:font-medium"/>
            <p className="art:mx-auto art:mt-4 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
              {copy.subhead}
            </p>
          </div>
          <div onMouseEnter={() => { paused.current = true; }} onMouseLeave={() => { paused.current = false; }} className="art:relative art:mt-14 art:flex art:flex-col art:gap-4 art:overflow-hidden art:[mask-image:linear-gradient(to_right,transparent,black_8%,black_92%,transparent)]">
            <div className="art:flex art:w-max">
              <motion.div ref={first} className="art:flex art:w-max art:gap-4" style={{ x: xFirst }}>
                {[...top, ...top].map(card)}
              </motion.div>
            </div>
            <div className="art:flex art:w-max">
              <motion.div ref={second} className="art:flex art:w-max art:gap-4" style={{ x: xSecond }}>
                {[...bottom, ...bottom].map(card)}
              </motion.div>
            </div>
          </div>
        </section>
      </div>
    </>);
}

